// Pass originalWidth when the original is already display-sized, so it stays the largest candidate.
const responsive = (src, sizes, originalWidth = 0) => {
  const stem = src.split('/').pop().replace(/\.(?:jpe?g|png|webp)$/i, '');
  const widths = imageCopies.map(file => file.startsWith(`${stem}-`) && /^(\d+)\.webp$/.exec(file.slice(stem.length + 1))?.[1]).filter(Boolean).map(Number).sort((a, b) => a - b);
  if (!widths.length) return `src="${e(src)}"`;
  const candidates = widths.map(w => [`assets/${stem}-${w}.webp`, w]);
  if (originalWidth > widths.at(-1)) candidates.push([src, originalWidth]);
  return `src="${e(candidates.at(-1)[0])}" srcset="${candidates.map(([file, w]) => `${e(file)} ${w}w`).join(', ')}" sizes="${sizes}"`;
};
