function page(name, title, description, body) {
  const card = shareCards.has(name) ? name : 'index';
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#ba0c2f"><meta name="color-scheme" content="light dark"><title>${e(title)} | Mobility Lab · UGA</title><meta name="description" content="${e(description)}">${name === '404' ? '<meta name="robots" content="noindex">' : `<link rel="canonical" href="${pageUrl(name)}"><meta property="og:url" content="${pageUrl(name)}">`}<meta property="og:title" content="${e(title)} | UGA Mobility Lab"><meta property="og:description" content="${e(description)}"><meta property="og:type" content="website"><meta property="og:site_name" content="UGA Mobility Lab"><meta property="og:image" content="${site}assets/share/${card}.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${e(title)}: UGA Mobility Lab"><meta name="twitter:card" content="summary_large_image">${structuredData[name] ? jsonLd(structuredData[name]) : ''}<link rel="icon" href="assets/favicon-32.png" sizes="32x32" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><script>document.documentElement.classList.add('js')</script><link rel="stylesheet" href="assets/site.css?v=${assetVersions.css}"><script defer src="assets/site.js?v=${assetVersions.js}" onerror="document.documentElement.classList.remove('js')"></script>${name === 'index' ? `<script defer src="assets/drive-game.js?v=${assetVersions.game}" onerror="document.documentElement.classList.add('no-drive-game')"></script><script defer src="assets/scan-viewer.js?v=${assetVersions.scan}"></script>` : ''}${name === 'research' ? `<script defer src="assets/traffic-wave.js?v=${assetVersions.wave}" onerror="document.documentElement.classList.add('no-traffic-wave')"></script>` : ''}</head><body id="top">${header(name)}<main id="main">${body}</main>${footer}</body></html>`;
  return name === '404' ? rooted(html) : html;
}
// The 404 page can be served at any depth, so its relative links start from the site root instead.
const siteRoot = '/.github/';
const isRelative = url => !/^(?:[a-z]+:|#|\/)/i.test(url);
