const threads = [
  { id:'robust-driving', legacy:'autonomy', title:'Robust driving', short:'Robust driving', icon:'car-front', headline:'Driving plans that hold up.', text:'We benchmark how camera corruption affects camera-only, end-to-end driving, find where planning starts to break down, and test in closed loop how much degradation a policy can tolerate. For vision-language planners, we sample candidate trajectories and verify them to pick better plans.', papers:['drivedegrade', 'sample-and-verify', 'camera-degradation-closed-loop'], methods:['End-to-end planning', 'Camera-corruption benchmarks', 'Trajectory verification', 'Closed-loop testing'], work:[paper('drivedegrade', 'DriveDegrade', 'WACV 2027'), paper('sample-and-verify', 'Sample-and-Verify', 'WACVW 2027'), paper('camera-degradation-closed-loop', 'Camera degradation', 'TRB 2027')], people:['haohua'],
    figure:{ src:'assets/drivedegrade-detail', width:2275, height:1062, alt:'Detail of the DriveDegrade overview: surround-view camera input and the degradation injector', tag:'DriveDegrade', href:'publications.html#drivedegrade' } },
  { id:'onboard-perception', title:'Efficient onboard perception', short:'Onboard perception', icon:'cpu', headline:'Perception that fits on the vehicle.', text:'Vehicles have limited power and strict deadlines. We plan from a few calibrated camera queries instead of a dense bird’s-eye view, run camera-based occupancy networks on FPGAs with latency that can be certified, and cut the energy of neural perception with motion-aware approximate memory.', papers:['falcon', 'lowp', 'motimem'], methods:['Sparse planning queries', 'FPGA acceleration', 'Latency certification', 'Approximate memory'], work:[paper('falcon', 'FALCON', 'WACV 2027'), paper('lowp', 'LOWP', 'WACVW 2027'), paper('motimem', 'MotiMem', 'WCCI 2026')], people:['haohua', 'tianle', 'qianyi'],
    figure:{ src:'assets/falcon-overview.png', width:2334, height:1043, alt:'FALCON overview: FPGA-accelerated occupancy network pipeline', tag:'FALCON', href:'publications.html#falcon' } },
  { id:'v2x-perception', legacy:'cooperation', title:'Cooperative V2X perception', short:'V2X perception', icon:'radio-tower', headline:'Vehicles that see beyond themselves.', text:'Vehicles and infrastructure can share what they see over V2X, but bandwidth is limited. We compress shared perception into compact tokens and use cloud-assisted encoding with large multimodal models to keep collaborative perception efficient.', papers:['dinolink', 'cable'], methods:['Token compression', 'LMM-based encoding', 'Cloud–edge collaboration'], work:[paper('dinolink', 'DinoLink', 'IROS 2026'), paper('cable', 'CABLE', 'SMC 2026')], people:['tianle', 'haohua', 'qianyi'],
    figure:{ src:'assets/dinolink-overview.webp', width:1800, height:700, alt:'DinoLink overview: token compression on the vehicle, V2X transmission, and detection on a cloud server', tag:'DinoLink', href:'publications.html#dinolink' } },
  { id:'scenes-robots', legacy:'robotics', title:'3D scenes & robot exploration', short:'3D scenes & robots', icon:'bot', headline:'Understanding places. Navigating possibilities.', text:'We regress 3D Gaussian scenes from RGB images and poses alone, localize and render large-scale scenes with mixture-of-experts coordinate encoding, and help robots explore and navigate by predicting the scene ahead.', papers:['acesplat', 'senseexpo', 'mace'], methods:['3D Gaussian splatting', 'Predictive exploration', 'Scene-coordinate localization'], work:[paper('acesplat', 'ACESplat', 'IROS 2026'), paper('senseexpo', 'SenseExpo', 'IROS 2026'), paper('mace', 'MACE', 'ICRA 2026')], people:['haohua', 'tianle'],
    figure:{ src:'assets/senseexpo-exploration.webp', width:814, height:354, alt:'SenseExpo exploration map: areas the robot has observed in orange, space it predicts is free in beige, and its path in red', tag:'SenseExpo · IROS 2026', href:'publications.html#senseexpo', photo:true } },
  { id:'vehicle-behavior', title:'Vehicle behavior in traffic', short:'Vehicle behavior', icon:'gauge', headline:'How automated and electric vehicles really drive.', text:'Field experiments and open datasets show how electric vehicles with one-pedal driving follow other cars, and how driver-assistance and automated driving systems interact with traffic lights and signs. We also study edge-computing operations for automated vehicles at stop-controlled intersections.', papers:['one-pedal-ctr', 'one-pedal-car-following', 'adas-traffic-signs', 'ads-traffic-sign-interactions', 'traffic-lights-signs-dataset', 'edge-computing-intersections'], more:[['resources.html#ev-platoon', 'EV car-following data']], methods:['Field experiments', 'Car-following models', 'Interaction datasets', 'Edge computing', 'Network simulation'], work:[paper('one-pedal-ctr', 'One-pedal EVs', 'CTR 2026'), paper('adas-traffic-signs', 'ADAS & signs', 'TRB 2027'), paper('traffic-lights-signs-dataset', 'AV–signal dataset', 'CTR 2025'), paper('edge-computing-intersections', 'Edge intersections', 'IET ITS 2025')], people:['tianle', 'qianyi', 'richard'],
    figure:{ src:'assets/ev-car-following-route-red', width:1453, height:738, alt:'Map of the GA-72 route between Hull and Comer, Georgia, used for EV car-following experiments', tag:'EV experiments · GA-72', href:'resources.html#ev-platoon', photo:true, attribution:'© OpenStreetMap contributors', attributionUrl:'https://www.openstreetmap.org/copyright' } },
  { id:'rural-roads', legacy:'infrastructure', title:'Rural roads, ready for autonomy', short:'Rural roads', icon:'route', headline:'Safer roads. Stronger communities.', text:'Through TRAVELS and related projects, we assess whether rural roads are ready for automated vehicles, map Georgia demonstration routes with LiDAR and HD maps, and synthesize the evidence on rural automated-vehicle deployment.', papers:['road-readiness-ictd'], more:[['travels.html', 'TRAVELS Georgia case study']], methods:['LiDAR HD mapping', 'Readiness assessment', 'Community engagement', 'Evidence synthesis'], work:[paper('road-readiness-ictd', 'Road readiness', 'ICTD 2026'), { href:'travels.html#hawkinsville-map', label:'Hawkinsville HD map', venue:'TRAVELS' }, { href:'resources.html#rav-evidence', label:'Rural AV evidence hub', venue:'Open data' }], people:['tianle', 'haohua'],
    figure:{ src:'assets/hawkinsville-lidar-hdmap.webp', width:1660, height:830, alt:'LiDAR point cloud and HD map of the Hawkinsville, Georgia demonstration route', tag:'Hawkinsville LiDAR & HD map', href:'travels.html#hawkinsville-map', photo:true, dark:true, scan:true } },
];
